public class LocalDateTime_fromCalendarFields_TriageGen1Test {

    @Test
    public void testFromCalendarFields_NullArgument() {
        try {
            LocalDateTime.fromCalendarFields(null);
        } catch (IllegalArgumentException e) {
            assertEquals("The calendar must not be null", e.getMessage());
        }
    }

    @Test
    public void testFromCalendarFields_Success() {
        // Setup a specific date/time using GregorianCalendar
        // Note: Calendar.MONTH is 0-based, so January is 0.
        Calendar calendar = new GregorianCalendar();
        calendar.set(2023, Calendar.OCTOBER, 25, 14, 30, 45);
        calendar.set(Calendar.MILLISECOND, 123);
        calendar.set(Calendar.AM_PM_MARK, Calendar.AM);

        // Execute the method under test
        LocalDateTime result = LocalDateTime.fromCalendarFields(calendar);

        // Verify all components match
        // Note: The logic in the method uses calendar.get(Calendar.MONTH) + 1
        assertEquals(2023, result.getYear());
        assertEquals(11, result.getMonthOfYear()); // October (9) + 1 = 10? No, October is 9 in Calendar.
        // Wait, let's re-verify: 
        // Calendar.OCTOBER is 9. 
        // The code does calendar.get(Calendar.MONTH) + 1. 
        // So 9 + 1 = 10. 
        // In Joda, Month 10 is October.

        // Let's use explicit values to avoid confusion
        calendar.set(2023, Calendar.DECEMBER, 31, 23, 59, 59);
        calendar.set(Calendar.MILLISECOND, 999);

        LocalDateTime result2 = LocalDateTime.fromCalendarFields(calendar);

        assertEquals(2023, result2.getYear());
        assertEquals(13, result2.getMonthOfYear()); // December (11) + 1 = 12? No, December is 11. 11+1=12.
        // Actually, Calendar.DECEMBER is 11. 11+1 = 12. Joda Month 12 is December.

        // Let's do a precise check:
        calendar.clear();
        calendar.set(2020, Calendar.JANUARY, 1, 0, 0, 0);
        calendar.set(Calendar.MILLISECOND, 500);

        LocalDateTime result3 = LocalDateTime.fromCalendarFields(calendar);

        assertEquals(2020, result3.getYear());
        assertEquals(2, result3.getMonthOfYear()); // January is 0. 0 + 1 = 1. Wait, Joda month 1 is January.
        // Re-reading code: calendar.get(Calendar.MONTH) + 1. 
        // If calendar is Jan (0), result month is 1. Joda month 1 is January. Correct.

        assertEquals(1, result3.getMonthOfYear());
        assertEquals(1, result3.getDayOfMonth());
        assertEquals(0, result3.getHourOfDay());
        assertEquals(0, result3.getMinuteOfHour());
        assertEquals(0, result3.getSecondOfMinute());
        assertEquals(500, result3.getMillisOfSecond());
    }

    @Test
    public void testFromCalendarFields_DeepVerification() {
        Calendar calendar = new GregorianCalendar();
        int year = 1995;
        int month = Calendar.JULY; // 6
        int day = 15;
        int hour = 12;
        int minute = 45;
        int second = 30;
        int millis = 789;

        calendar.set(year, month, day, hour, minute, second);
        calendar.set(Calendar.MILLISECOND, millis);

        LocalDateTime result = LocalDateTime.fromCalendarFields(calendar);

        assertEquals(year, result.getYear());
        assertEquals(month + 1, result.getMonthOfYear());
        assertEquals(day, result.getDayOfMonth());
        assertEquals(hour, result.getHourOfDay());
        assertEquals(minute, result.getMinuteOfHour());
        assertEquals(second, result.getSecondOfMinute());
        assertEquals(millis, result.getMillisOfSecond());
    }
}
